async function renderNode() {
  const id = getParam('id');
  if (!id) {
    throw new Error('Missing node id');
  }

  const padId = String(id).padStart(3, '0');
  const [data, somData] = await Promise.all([
    loadJSON(`data/nodes/node_${padId}.json`),
    loadJSON('data/nodes.json')
  ]);

  const titleEl = document.getElementById('node-title');
  const statsEl = document.getElementById('node-stats');
  const medoidEl = document.getElementById('medoid');
  const tableLink = document.getElementById('node-table-link');
  const memberBrowser = document.getElementById('member-browser');
  const viewModeSel = document.getElementById('viewMode');
  const rankedCountSel = document.getElementById('rankedCount');
  const pageSizeSel = document.getElementById('pageSize');
  const pageControls = document.getElementById('pageControls');
  const rankedWrap = document.getElementById('rankedCountWrap');
  const pageWrap = document.getElementById('pageSizeWrap');

  // NEW: sort control
  const sortSel = document.getElementById('sortDir');

  const members = Array.isArray(data.members) ? data.members : [];
  const prefs = loadNodePrefs();
  let currentPage = 1;

  titleEl.textContent = `Node ${data.node_id}`;

  viewModeSel.value = (prefs.viewMode === 'all') ? 'all' : 'ranked';
  rankedCountSel.value = ['5', '10', '50', '100'].includes(prefs.rankedCount) ? prefs.rankedCount : '10';
  pageSizeSel.value = ['10', '25', '50', '100'].includes(prefs.pageSize) ? prefs.pageSize : '50';

  // NEW: sort default
  if (!prefs.sortDir) prefs.sortDir = 'asc';
  sortSel.value = prefs.sortDir;

  const s = data.stats;
  statsEl.innerHTML = `
    <table>
      <tr><td>full_count</td><td>${s.full_count}</td></tr>
      <tr><td>train_count</td><td>${s.train_count}</td></tr>
      <tr><td>ratio</td><td>${fmt(s.ratio)}</td></tr>
      <tr><td>median_p2p</td><td>${fmtSmart(s.median_p2p)}</td></tr>
      <tr><td>median_snr_var</td><td>${fmtSmart(s.median_snr_var)}</td></tr>
      <tr><td>median_rms</td><td>${fmtSmart(s.median_rms)}</td></tr>
      <tr><td>Trust</td><td>${fmt(s.Trust)}</td></tr>
      <tr><td>Cont</td><td>${fmt(s.Cont)}</td></tr>
      <tr><td>McycD_pw</td><td>${fmtSmart(s.McycD_pw)}</td></tr>
      <tr><td>topo_errRate</td><td>${fmtSmart(s.topo_errRate)}</td></tr>
    </table>
    <div class="node-mini-map-wrap">
      <div class="node-mini-map-title">Node location</div>
      ${makeMiniHexMap(somData.nodes, data.node_id, { width: 220, height: 170, r: 7 })}
    </div>
  `;

  medoidEl.innerHTML = `
    <div>
      <div style="font-weight:600; margin-bottom:6px;">Medoid Â± MAD</div>
      <a href="node.html?id=${data.node_id}" class="medoid-link">
        <img
          src="img/nodes/node_${padId}_mad.png"
          alt="Node medoid plus MAD"
          style="display:block; max-width:100%; height:auto;"
        >
      </a>
    </div>
  `;

  const ticCache = new Map();

  async function loadTICData(tic) {
    if (ticCache.has(tic)) return ticCache.get(tic);
    const bucket = ticBucket(tic);
    const promise = loadJSON(`data/tic/${bucket}/tic_${tic}.json`);
    ticCache.set(tic, promise);
    return promise;
  }

  async function loadSectorForMember(m) {
    try {
      const ticData = await loadTICData(m.tic);
      const sectors = getSectorsArray(ticData);
      return sectors.find(x => Number(x.sector) === Number(m.sector)) || null;
    } catch (err) {
      return null;
    }
  }

  async function makeTile(m) {
    const sec = await loadSectorForMember(m);

    let lcHTML = '<div class="plot-missing">No LC data</div>';
    if (
      sec &&
      Array.isArray(sec.display_t) &&
      Array.isArray(sec.display_f) &&
      sec.display_t.length > 0 &&
      sec.display_f.length > 0
    ) {
      lcHTML = `<a class="lc-plot-link" href="${m.lc_page}">${makeLCPlot(sec.display_t, sec.display_f, 260, 120, { compact: true })}</a>`;
    }

    return `
      <div class="lc-tile">
        <div class="lc-meta lc-meta-compact">
          ${makeCompactMemberText(m, true)}
        </div>
        ${lcHTML}
      </div>
    `;
  }

  async function renderGallery(subset) {
    if (!subset.length) return '<div class="empty-note">No members to display.</div>';
    const tiles = await Promise.all(subset.map(makeTile));
    return `<div class="gallery-grid">${tiles.join('')}</div>`;
  }

  function syncPrefs() {
    prefs.viewMode = viewModeSel.value;
    prefs.rankedCount = rankedCountSel.value;
    prefs.pageSize = pageSizeSel.value;
    prefs.sortDir = sortSel.value; // NEW
    saveNodePrefs(prefs);
  }

  function updateControlVisibility() {
    const mode = viewModeSel.value;
    rankedWrap.style.display = mode === 'ranked' ? '' : 'none';
    pageWrap.style.display = mode === 'all' ? '' : 'none';

    // NEW: show sort only in "all"
    if (sortSel) {
      sortSel.parentElement.style.display = mode === 'all' ? '' : 'none';
    }
  }

  function renderPager(total, pageSize) {
    const nPages = Math.max(1, Math.ceil(total / pageSize));
    if (currentPage > nPages) currentPage = nPages;
    if (nPages <= 1) {
      pageControls.innerHTML = '';
      return;
    }

    pageControls.innerHTML = `
      <button type="button" id="nodePrevPage" ${currentPage <= 1 ? 'disabled' : ''}>Prev</button>
      <span class="page-status">Page ${currentPage} of ${nPages}</span>
      <button type="button" id="nodeNextPage" ${currentPage >= nPages ? 'disabled' : ''}>Next</button>
    `;

    document.getElementById('nodePrevPage').addEventListener('click', async () => {
      if (currentPage > 1) {
        currentPage -= 1;
        await updateMemberBrowser();
      }
    });
    document.getElementById('nodeNextPage').addEventListener('click', async () => {
      if (currentPage < nPages) {
        currentPage += 1;
        await updateMemberBrowser();
      }
    });
  }

  async function updateMemberBrowser() {
    syncPrefs();
    updateControlVisibility();

    const mode = viewModeSel.value;

    if (mode === 'ranked') {
      const n = Number(rankedCountSel.value);
      const topMembers = members.slice(0, n);
      const botMembers = n > 0 ? members.slice(Math.max(0, members.length - n)) : [];
      pageControls.innerHTML = '';

      const [topHTML, botHTML] = await Promise.all([
        renderGallery(topMembers),
        renderGallery(botMembers)
      ]);

      memberBrowser.innerHTML = `
        <div class="member-browser-section">
          <h3>Top-ranked members</h3>
          ${topHTML}
        </div>
        <div class="member-browser-section">
          <h3>Bottom-ranked members</h3>
          ${botHTML}
        </div>
      `;
      return;
    }

    // --- SHOW ALL MODE WITH SORT ---
    const pageSize = Number(pageSizeSel.value);

    let ordered = members;
    if (sortSel.value === 'desc') {
      ordered = members.slice().reverse();
    }

    const nPages = Math.max(1, Math.ceil(ordered.length / pageSize));
    if (currentPage < 1) currentPage = 1;
    if (currentPage > nPages) currentPage = nPages;

    const start = (currentPage - 1) * pageSize;
    const stop = Math.min(start + pageSize, ordered.length);
    const subset = ordered.slice(start, stop);

    const html = await renderGallery(subset);
    renderPager(ordered.length, pageSize);

    memberBrowser.innerHTML = `
      <div class="member-browser-section">
        <div class="member-browser-summary">
          Showing members ${start + 1}-${stop} of ${ordered.length}
        </div>
        ${html}
      </div>
    `;
  }

  viewModeSel.addEventListener('change', async () => {
    currentPage = 1;
    await updateMemberBrowser();
  });

  rankedCountSel.addEventListener('change', async () => {
    currentPage = 1;
    await updateMemberBrowser();
  });

  pageSizeSel.addEventListener('change', async () => {
    currentPage = 1;
    await updateMemberBrowser();
  });

  // NEW: sort change
  sortSel.addEventListener('change', async () => {
    currentPage = 1;
    await updateMemberBrowser();
  });

  await updateMemberBrowser();

  const header = ['TIC', 'Sector', 'rank_bmu', 'dbmu_pct', 'dist_bmu', 'status', 'p2p', 'snr_var', 'rms'];
  const rows = members.map(m => [
    m.tic,
    m.sector,
    m.rank_bmu,
    m.dbmu_pct,
    m.dist_bmu,
    m.status,
    m.p2p,
    m.snr_var,
    m.rms
  ]);

  const csv = [header, ...rows]
    .map(r => r.map(x => String(x ?? '')).join(','))
    .join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  tableLink.href = url;
  tableLink.download = `node_${padId}_members.csv`;
}

async function renderTIC() {
  const tic = getParam('tic');
  if (!tic) {
    throw new Error('Missing TIC');
  }

  const [data, somData] = await Promise.all([
    loadJSON(`data/tic/${ticBucket(tic)}/tic_${tic}.json`),
    loadJSON('data/nodes.json')
  ]);

  const headerEl = document.getElementById('tic-header');
  const tableEl = document.getElementById('tic-table');
  const simbadURL = `https://simbad.u-strasbg.fr/simbad/sim-basic?Ident=TIC+${tic}`;

  headerEl.innerHTML = `
    <div class="tic-header-box">
      <h1>TIC ${data.tic}</h1>

      <div class="tic-header-meta">
        <div class="tic-meta-left">
          <div>Total sectors: ${data.repeat_summary.n_sector_total}</div>
          <div>Valid sectors: ${data.repeat_summary.n_sector_valid}</div>
          <div>Distinct nodes: ${data.repeat_summary.n_node}</div>
        </div>

        <div class="tic-meta-right">
          <a class="simbad-link" href="${simbadURL}" target="_blank" rel="noopener noreferrer">
            Search in SIMBAD
          </a>
        </div>
      </div>
    </div>
  `;

  const sectors = getSectorsArray(data);

  const rows = sectors.map(s => {
    const lcPage = `lc.html?tic=${data.tic}&sector=${s.sector}`;
    const lcHTML = (
      Array.isArray(s.display_t) &&
      Array.isArray(s.display_f) &&
      s.display_t.length > 0 &&
      s.display_f.length > 0
    )
      ? `<a class="lc-plot-link" href="${lcPage}">${makeLCPlot(s.display_t, s.display_f, 260, 120, { compact: true })}</a>`
      : '<div class="plot-missing">No LC data</div>';

    const miniMapHTML = s.has_result
      ? makeMiniHexMap(somData.nodes, s.node_id, { width: 150, height: 118, r: 5, pad: 10 })
      : '';

    if (!s.has_result) {
      return `
        <div class="tic-row tic-row-3col">
          <div class="tic-row-left">
            <div class="tic-row-title">Sector ${s.sector}</div>
            <div class="tic-row-meta">Status ${s.status} &nbsp; No result</div>
            <div class="tic-row-links">
              <a href="${lcPage}">LC page</a>
            </div>
          </div>
          <div class="tic-row-right">
            ${lcHTML}
          </div>
          <div class="tic-row-map"></div>
        </div>
      `;
    }

    return `
      <div class="tic-row tic-row-3col">
        <div class="tic-row-left">
          <div class="tic-row-title">Sector ${s.sector}</div>
          <div class="tic-row-meta">
            Status ${s.status}
            &nbsp; Node <a href="node.html?id=${s.node_id}">${s.node_id}</a>
            &nbsp; Rank ${s.rank_bmu}
            &nbsp; dist_bmu ${fmtSmart(s.dist_bmu)}
            &nbsp; p2p ${fmtSmart(s.p2p)}
            &nbsp; snr_var ${fmtSmart(s.snr_var)}
            &nbsp; rms ${fmtSmart(s.rms)}
          </div>
          <div class="tic-row-links">
            <a href="${lcPage}">LC page</a>
          </div>
        </div>
        <div class="tic-row-right">
          ${lcHTML}
        </div>
        <div class="tic-row-map">
          ${miniMapHTML}
        </div>
      </div>
    `;
  }).join('');

  tableEl.innerHTML = `<div class="tic-list">${rows}</div>`;
}

async function renderLC() {
  const tic = getParam('tic');
  const sector = Number(getParam('sector'));

  if (!tic) {
    throw new Error('Missing TIC');
  }
  if (!Number.isFinite(sector)) {
    throw new Error('Missing or invalid sector');
  }

  const data = await loadJSON(`data/tic/${ticBucket(tic)}/tic_${tic}.json`);
  const sectors = getSectorsArray(data);
  const s = sectors.find(x => Number(x.sector) === sector);

  const headerEl = document.getElementById('lc-header');
  const mainEl = document.getElementById('lc-main');
  const neighEl = document.getElementById('neighbors');

  headerEl.innerHTML = `<h1><a href="tic.html?tic=${tic}">TIC ${tic}</a> | Sector ${sector}</h1>`;

  if (!s) {
    mainEl.innerHTML = `
      <div class="panel">
        <p>Sector ${sector} not found for TIC ${tic}.</p>
        <p><a href="tic.html?tic=${tic}">Open TIC page</a></p>
      </div>
    `;
    neighEl.innerHTML = '';
    return;
  }

  const hasDisplay = Array.isArray(s.display_t) && Array.isArray(s.display_f) && s.display_t.length > 0 && s.display_f.length > 0;

  if (!s.has_result) {
    mainEl.innerHTML = `
      <section class="panel">
        <div class="lc-main-meta">
          <div>Status ${s.status}</div>
        </div>
        <div class="lc-main-plot">
          ${hasDisplay ? makeLCPlot(s.display_t, s.display_f, 760, 260) : '<div class="plot-missing">No LC data</div>'}
        </div>
        <div class="lc-note">
          Display note: this plot is a thinned display representation of the light curve, not the full cadence time series.
        </div>
      </section>
    `;
    neighEl.innerHTML = '';
    return;
  }

  const lcPlot = hasDisplay
    ? makeLCPlot(s.display_t, s.display_f, 760, 260)
    : '<div class="plot-missing">No LC data</div>';

  mainEl.innerHTML = `
    <section class="panel">
      <div class="lc-main-meta">
        <div>Node: <a href="node.html?id=${s.node_id}">${s.node_id}</a></div>
        <div>Rank: ${s.rank_bmu}</div>
        <div>dist_bmu: ${fmtSmart(s.dist_bmu)}</div>
        <div>p2p: ${fmtSmart(s.p2p)}</div>
        <div>snr_var: ${fmtSmart(s.snr_var)}</div>
        <div>rms: ${fmtSmart(s.rms)}</div>
      </div>

      <div class="lc-main-plot">
        ${lcPlot}
      </div>

      <div class="lc-note">
        Display note: this plot is a thinned display representation of the light curve, not the full cadence time series.
      </div>

      <div class="lc-medoid-block">
        <div style="font-weight:600; margin-bottom:6px;">Node medoid Â± MAD</div>
        <a href="node.html?id=${s.node_id}" class="medoid-link">
          <img
            src="${s.node_medoid_img}"
            alt="Node medoid plus MAD"
            style="display:block; max-width:100%; height:auto;"
          >
        </a>
      </div>
    </section>
  `;

  const ticCache = new Map();
  async function loadTICData(ticId) {
    if (ticCache.has(ticId)) return ticCache.get(ticId);
    const promise = loadJSON(`data/tic/${ticBucket(ticId)}/tic_${ticId}.json`);
    ticCache.set(ticId, promise);
    return promise;
  }

  async function makeNeighborTile(n) {
    let lcHTML = '<div class="plot-missing">No LC data</div>';

    try {
      const tdat = await loadTICData(n.tic);
      const secs = getSectorsArray(tdat);
      const sec = secs.find(x => Number(x.sector) === Number(n.sector));

      if (
        sec &&
        Array.isArray(sec.display_t) &&
        Array.isArray(sec.display_f) &&
        sec.display_t.length > 0 &&
        sec.display_f.length > 0
      ) {
        lcHTML = `<a class="lc-plot-link" href="${n.lc_page}">${makeLCPlot(sec.display_t, sec.display_f, 260, 120, { compact: true })}</a>`;
      }
    } catch (err) {
      lcHTML = '<div class="plot-missing">No LC data</div>';
    }

    return `
      <div class="lc-tile">
        <div class="lc-meta lc-meta-compact">
          ${makeCompactMemberText(n, true,false)}
        </div>
        ${lcHTML}
      </div>
    `;
  }

  const neighbors = Array.isArray(s.neighbors) ? s.neighbors : [];
  if (!neighbors.length) {
    neighEl.innerHTML = '';
    return;
  }

  const tiles = await Promise.all(neighbors.map(makeNeighborTile));
  neighEl.innerHTML = `
    <section class="panel">
      <h2>Feature-space neighbors from the training set of periodic source</h2>
      <div class="gallery-grid">${tiles.join('')}</div>
    </section>
  `;
}

window.addEventListener('DOMContentLoaded', async () => {
  try {
    const page = document.body.dataset.page;
    if (page === 'som') await renderSOM();
    if (page === 'node') await renderNode();
    if (page === 'tic') await renderTIC();
    if (page === 'lc') await renderLC();
  } catch (err) {
    console.error(err);
    const pre = document.createElement('pre');
    pre.textContent = String(err);
    document.body.appendChild(pre);
  }
});
